let state=null,assets={pet:{},buildings:{},scenes:[]},layout=null,connected=false,busy=false,pip=null;
let lastTownSignature='',lastTaskSignature='',lastGraveSignature='',lastWeather='',lastPetSource='',townBlobURL='',petBlobURL='';
let recording=false,pressed=false,recorder=null,stream=null,recordTimeout=null,selectedView='wide',viewIndex=0,currentReminder=null,petCacheStage='',lastCacheAt=0,pendingCommand=null;
