async function saveReviewedCommand(event){event.preventDefault();if(!pendingCommand||$('save-review').disabled)return;const command=structuredClone(pendingCommand);for(const[index,task]of command.tasks.entries()){const titleInput=$('review-title-'+index),stepInput=$('review-step-'+index);const correctedTitle=titleInput.value.trim(),correctedStep=stepInput.value.trim();if(!correctedTitle||!correctedStep){text('review-feedback','Give each task a name and a first step before saving.');(!correctedTitle?titleInput:stepInput).focus();return;}if(correctedTitle!==task.title)task.label=correctedTitle.slice(0,20);task.title=correctedTitle;task.tiny_first_step=correctedStep;for(const field of ['due','remind_at']){const input=$('review-'+field+'-'+index);if(input.value!==input.dataset.original)task[field]=input.value||null;}}$('save-review').disabled=true;text('review-feedback','Daytown is saving your tasks.');try{const result=await request('/api/commit-command',{command});applyState(result.state);pendingCommand=null;$('review-dialog').close();if($('command'))$('command').value='';note('Your tasks have been saved.');}catch(error){text('review-feedback',error.message);const match=String(error.field||'').match(/^tasks\[(\d+)\]\.(due|remind_at)$/);if(match){const field=$('review-'+match[2]+'-'+match[1]);field?.setAttribute('aria-invalid','true');field?.focus();}}finally{$('save-review').disabled=false;}}
async function command(textValue){if(busy||!textValue.trim())return;busy=true;render();if($('send'))$('send').disabled=true;note('Daytown is checking the tasks and dates.');try{const parsed=await request('/api/parse',{text:textValue});if(parsed.command.needs_clarification){note(parsed.command.clarification_question||'Which task did you finish?');return;}if(parsed.command.action==='add'){reviewCommand(parsed.command,textValue);return;}const targetId=parsed.command.task_id||state?.nextTaskId;const result=await request('/api/commit-command',{command:parsed.command});applyState(result.state);if(result.action==='show_week')openWeek();else if(['move','remind','snooze'].includes(result.action)){const task=result.state.tasks.find(task=>task.id===targetId);if(task){const when=result.action==='move'?task.due:task.remind_at;note('“'+task.title+'” '+(result.action==='move'?'is due on ':'will remind you on ')+formatLondonDate(when)+'.');}else note('Your task dates have been updated.');}else note(result.reply||(result.action==='done'?'That is one less thing on your mind.':'Your next step is displayed above.'));if(preferences.voice&&result.reply&&['ready','gassed'].includes(result.action))playVoice(result.reply);if($('command'))$('command').value='';}catch(error){note(error.message);}finally{busy=false;if($('send'))$('send').disabled=false;render();}}
async function debug(body){try{const result=await request('/api/debug',body);applyState(result.state);note(body.action==='advance'?`Demo clock moved ${body.minutes} minutes ahead.`:body.action==='seed'?'The sample tasks have been loaded.':'Your tasks have been updated.');}catch(error){note(error.message);}}
function fireworks(taskId){const root=$('fireworks');if(!root)return;let x=50,y=40;const plot=layout?.plots?.find(p=>p.taskId===taskId);if(plot){x=(plot.x+plot.width/2)/layout.width*100;y=(plot.y+plot.height/2)/layout.height*100;}for(let i=0;i<55;i++){const part=document.createElement('i');part.className='firework';part.style.setProperty('--fx',x+'%');part.style.setProperty('--fy',y+'%');part.style.setProperty('--x',`${(Math.random()-.5)*330}px`);part.style.setProperty('--y',`${(Math.random()-.65)*270}px`);part.style.setProperty('--c',['#e6bd83','#a5be8b','#b5a4cb','#eeac94','#f5e4ad'][i%5]);root.append(part);setTimeout(()=>part.remove(),1700);}}
async function openWeek(){if(!$('week-dialog')){if(extension)chrome.tabs.create({url:API+'/?week=1'});else location.href=API+'/?week=1';return;}const image=$('poster-image');image.src=`${API}/api/poster.png?r=${state?.revision||0}`;image.onerror=()=>{image.hidden=true;note('Your weekly poster is being prepared. Please try again shortly.');};image.onload=()=>image.hidden=false;$('download-poster').href=`${API}/api/poster.png?r=${state?.revision||0}`;const done=state?.tasks.filter(t=>t.status==='done').length||0;text('poster-summary',`You completed ${done} ${done===1?'task':'tasks'} this week and remembered ${state?.graves.length||0} ${state?.graves.length===1?'pet':'pets'}. Download the poster to keep a copy.`);$('week-dialog').showModal();}
