function updatePip(){if(!pip||pip.closed||!state)return;const doc=pip.document,task=nextTask();doc.title='Daytown · '+(codexPet.connected?codexPet.name:state.pet.name);updatePet(doc.querySelector('.pet-art'),state.pet.stage);doc.getElementById('pip-step').textContent=state.pet.stage==='egg'?'Finish one step to hatch again.':task?.tiny_first_step||'You have no unfinished tasks.';const reminderSoon=task?.remind_at&&Date.parse(task.remind_at)-Date.parse(state.now)<15*60000&&Date.parse(task.remind_at)-Date.parse(state.now)>-60000;const sign=doc.getElementById('pip-sign');sign.hidden=!reminderSoon&&!currentReminder;sign.textContent=currentReminder?.label||(reminderSoon?task.label:'');doc.getElementById('pip-health').textContent=state.pet.stage==='ghost'?'Your pet has died.':state.pet.stage==='egg'?'Finish a step to hatch.':`${state.pet.name} · ${Math.round(state.pet.health)} / 100`;doc.getElementById('pip-done').disabled=!task||busy||!connected;doc.getElementById('pip-focus').disabled=!task||busy||!connected;}
async function showReminder(event){const task=state?.tasks.find(t=>t.id===event.taskId)||nextTask();if(!task)return;currentReminder={label:task.label};updatePip();if(pip&&!pip.closed){pip.document.body.classList.remove('reminding');void pip.document.body.offsetWidth;pip.document.body.classList.add('reminding');}setTimeout(()=>{currentReminder=null;updatePip();},20000);let willNotify=preferences.notifications&&(!pip||pip.closed)&&'Notification'in window&&Notification.permission==='granted';if(willNotify){try{const presence=await request('/api/pet-presence');willNotify=!presence.open;}catch{willNotify=false;}}if(!preferences.voice&&!willNotify)return;const key=`${task.id}:${task.reminderFiredAt||task.remind_at||task.due||state.now}`;try{const claim=await request('/api/reminders/claim',{taskId:task.id,reminderAt:task.reminderFiredAt});if(!claim.claimed)return;}catch{return;}const line=String(event.text||`${task.label}. Reminder due.`).slice(0,300);if(preferences.voice)playVoice(line);if(willNotify)new Notification('Daytown reminder',{body:line,tag:key});}
