async function startRecording(){if(pressed||recording||busy)return;pressed=true;try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw new Error('Use Chrome on localhost for microphone recording.');stream=await navigator.mediaDevices.getUserMedia({audio:true});if(!pressed){stream.getTracks().forEach(track=>track.stop());return;}const type=['audio/webm;codecs=opus','audio/webm','audio/mp4'].find(value=>MediaRecorder.isTypeSupported(value));recorder=new MediaRecorder(stream,type?{mimeType:type}:{});const chunks=[];const startedAt=performance.now();recorder.ondataavailable=event=>{if(event.data.size)chunks.push(event.data);};recorder.onstop=async()=>{clearTimeout(recordTimeout);stream.getTracks().forEach(track=>track.stop());recording=false;$('mic')?.classList.remove('recording');const audio=new Blob(chunks,{type:recorder.mimeType});if(performance.now()-startedAt<450||audio.size<100){note('Hold the microphone while you speak.');return;}busy=true;note('Daytown is transcribing your recording.');try{const result=await request('/api/transcribe',audio,{'Content-Type':audio.type});busy=false;await command(result.text);}catch(error){note(error.message);}finally{busy=false;render();}};recorder.start();recording=true;$('mic')?.classList.add('recording');note('Release the microphone when you finish speaking.');recordTimeout=setTimeout(stopRecording,45000);}catch(error){pressed=false;stream?.getTracks().forEach(track=>track.stop());note(error.name==='NotAllowedError'?'Allow microphone access in Chrome, then hold to talk again.':error.message);}}
