function setupExamples(){const composer=document.querySelector('.brain-dump');if(!composer||!$('command'))return;const examples=document.createElement('div');examples.className='task-examples';const label=document.createElement('span');label.textContent='Try an example';const chips=document.createElement('div');chips.className='example-chips';for(const example of ['Fix auth tests tomorrow at 10','Review PR 42 Friday at 2','Remind me to stretch in 20 minutes']){const button=document.createElement('button');button.type='button';button.textContent=example;button.onclick=()=>{$('command').value=example;$('command').focus();note('You can edit the example, then send it when you’re ready.');};chips.append(button);}examples.append(label,chips);composer.after(examples);const grid=document.querySelector('.main-grid');if(grid)grid.before(composer,examples,$('feedback'));}
setupThemeControl();setupExamples();setupWorkbenchActor();setupTaskTools();
function setupCodexConnection(){const card=document.createElement('section');card.className='codex-connect-card';card.id='codex-connect-card';card.innerHTML='<div><h2>Connect your Codex pet</h2><p>Use the pet you selected in Codex for Daytown’s reminders.</p><p id="codex-pet-feedback" role="status" aria-live="polite"></p></div><button class="button dark" id="connect-codex">Connect Codex</button>';const header=document.querySelector('.topbar,.panel-header');header?.after(card);if(!header)return;const settings=document.createElement('details');settings.className='pet-settings';settings.id='pet-settings';settings.hidden=true;settings.innerHTML='<summary>Pet settings</summary><p id="codex-pet-status"></p><button class="button quiet" id="reconnect-codex">Reconnect</button><p id="codex-activity"></p><p id="codex-link-status"></p><button class="button quiet" id="link-codex-activity">Link Codex activity</button>';document.querySelector('.pet-card,.panel-companion')?.after(settings);$('connect-codex').onclick=connectCodexPet;$('reconnect-codex').onclick=connectCodexPet;$('link-codex-activity').onclick=async()=>{try{await request('/api/codex-link',{});await refreshCodexActivityLink();note('Codex turn-complete signals are linked for new sessions.');}catch(error){note(error.message);}};if(!appMode){const button=document.createElement('button');button.id='open-app';button.className='button quiet';button.textContent='Open app';button.onclick=async()=>{try{await request('/api/app-launch',{});note('The Daytown application is open.');}catch{note('Daytown could not open the application. Please try again.');}};const actions=document.querySelector('.top-actions');if(actions)actions.insertBefore(button,$('float-pet'));else document.querySelector('.panel-float')?.after(button);}$('float-pet')?.replaceChildren(document.createTextNode('Pin workbench'));}
function renderCodexConnection(){hide('codex-connect-card',codexPet.connected);hide('pet-settings',!codexPet.connected);text('codex-pet-status',codexPet.connected?codexPet.name+' is connected.':'');if(codexConnectionError)text('codex-pet-feedback',codexConnectionError);else if(!codexPet.connected&&!codexPet.available)text('codex-pet-feedback','Choose a pet in Codex, then connect it here.');else if(!connectingCodex)text('codex-pet-feedback','');for(const id of ['connect-codex','reconnect-codex'])if($(id))$(id).disabled=connectingCodex;setConnection(connected);if(state)text('pet-name',codexPet.connected?codexPet.name:state.pet.name);}
async function refreshCodexPet(){try{codexPet=await request('/api/codex-pet');renderCodexConnection();}catch{text('codex-pet-feedback','Daytown could not check your selected pet. You can try connecting it here.');}}
async function connectCodexPet(){if(connectingCodex)return;connectingCodex=true;codexConnectionError='';renderCodexConnection();text('codex-pet-feedback','Daytown is connecting your selected pet.');try{const result=await request('/api/codex-pet/connect',{});codexPet={connected:!!result.connected,available:true,name:result.name||'your pet'};if(result.state)applyState(result.state);await loadAssets();renderCodexConnection();note(codexPet.name+' is connected.');}catch{codexConnectionError='Daytown could not connect your selected pet. Please try again.';text('codex-pet-feedback',codexConnectionError);}finally{connectingCodex=false;renderCodexConnection();}}
setupCodexConnection();
async function consumeCompanionDraft(){if(extension||busy||pendingCommand)return;let draft;try{draft=JSON.parse(localStorage.getItem('daytown-companion-draft')||'null');}catch{return;}if(!draft?.command||draft.command.action!=='add')return;localStorage.removeItem('daytown-companion-draft');reviewCommand(draft.command,draft.text||'');}
window.addEventListener('storage',event=>{if(event.key==='daytown-companion-draft'&&event.newValue)consumeCompanionDraft();});window.addEventListener('focus',consumeCompanionDraft);
async function initialize(){Object.assign(preferences,await storageGet(prefsKey)||{});applyTheme();if($('voice-enabled'))$('voice-enabled').checked=preferences.voice;if($('notifications-enabled'))$('notifications-enabled').checked=preferences.notifications;if($('float-pet')){$('float-pet').disabled=false;$('float-pet').title='Pin the workbench above your other windows';}if($('browser-pet'))$('browser-pet').disabled=!window.documentPictureInPicture;
 const cached=extension?await storageGet(cacheKey):null;if(cached?.assets)assets=cached.assets;
 const previousView=await storageGet(viewKey)||{index:-1,greeting:-1};let view;
 try{view=extension?await chrome.runtime.sendMessage({kind:'daytown-next-view',hasScenes:!!assets.scenes?.length}):null;}catch{}
 if(!view){view=nextView(previousView,!!assets.scenes?.length);await storageSet(viewKey,view);}
 viewIndex=view.index;selectedView=newtab?view.mode:'wide';const greetingIndex=view.greeting;if(newtab){$('town-scene')?.classList.add(selectedView);text('view-badge',{wide:'At your desk',close:'Your next note',street:'At your workbench',story:'At your workbench'}[selectedView]);const greeting=$('greeting');if(greeting){greeting.replaceChildren();greeting.textContent=greetings[greetingIndex];}}
 if(extension&&cached?.state){petBlobURL=cached.pet||'';petCacheStage=cached.petStage||'';state=cached.state;render();if(cached.town){$('town-image').src=cached.town;$('town-image').hidden=false;hide('town-placeholder',true);townBlobURL=cached.town;}text('newtab-status','Daytown is reconnecting while showing your saved view.');}
 try{const next=await request('/api/state');setConnection(true);applyState(next);await refreshCodexPet();await refreshCodexActivityLink();await loadAssets();await consumeCompanionDraft();if(newtab){const seen=await storageGet('daytown-seen-v1');const done=state.tasks.filter(t=>t.status==='done').length,graves=state.graves.length;if(seen&&(done>seen.done||graves>seen.graves)){text('day-label','Updated');text('newtab-status',`${Math.max(0,done-seen.done)} new completed tasks · ${Math.max(0,graves-seen.graves)} past pets since your last visit`);}else text('newtab-status','Your next step is ready.');storageSet('daytown-seen-v1',{done,graves});}if(new URLSearchParams(location.search).has('week'))openWeek();}catch{setConnection(false);note(extension&&state?'Start Daytown to update your saved tasks.':'Start Daytown on this computer to update your tasks.');}
 const events=new EventSource(API+'/api/events');events.onopen=()=>setConnection(true);events.onerror=()=>setConnection(false);events.onmessage=event=>{try{const data=JSON.parse(event.data);if(data.state)applyState(data.state);if(data.kind==='celebration')fireworks(data.taskId);if(data.kind==='pop')showPop(data);if(data.kind==='reminder')showReminder(data);if(data.kind==='assets')loadAssets();if(data.kind==='death'){note('Your pet has died. Complete a step to hatch a new one.');lastTownSignature='';refreshTown();}}catch{}};
 setInterval(loadAssets,10000);setInterval(()=>{renderFocus();updatePip();},1000);
}
setInterval(()=>{if(pip&&!pip.closed)publishPetPresence(true);},15000);
window.addEventListener('pagehide',()=>{if(pip&&!pip.closed)fetch(API+'/api/pet-presence',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({clientId,open:false}),keepalive:true}).catch(()=>{});});
initialize();
